def triples_sum_to_zero(l: list) -> bool:
    l.sort()
    n = len(l)
    for i in range(n - 2):
        left, right = (i + 1, n - 1)
        while left < right:
            current_sum = l[i] + l[left] + l[right]
            if 0 == current_sum:
                return True
            elif 0 > current_sum:
                left = left + 1
            else:
                right = right - 1
    return False

