def shell_sort(power_seen):
    n = len(power_seen)
    gap = n // 2
    while 0 < gap:
        for i in range(gap, n):
            temp = power_seen[i]
            j = i - gap
            while 0 <= j and power_seen[j] > temp:
                power_seen[j + gap] = power_seen[j]
                j = j - gap
            power_seen[j + gap] = temp
        gap = gap // 2
    return power_seen

